# POST /api/sheets/{sheetId}/claims/{claimId}/redate — re-date an OPEN or PENDING claim (body {date, user}).
# The claim keeps its due-by and any figure a statement bound it to, and so its period (the one its due-by
# falls in) and its number. Refused (400) when the user is not a steward, the date
# does not parse or is after the date the person is retired from, the claim is not OPEN or PENDING or not
# on the sheet, or its due-by falls in a closed period; nothing is stored then. A stored
# re-dating is recorded in the audit file as CLAIM_REDATED.
validate:
  class: net.officefloor.hq.app.claim.ValidateRedate
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkClaim
checkClaim:
  class: net.officefloor.hq.app.claim.CheckClaimPeriod
  govern: [ transaction ]
  next: checkRedate
checkRedate:
  class: net.officefloor.hq.app.claim.CheckRedate
  govern: [ transaction ]
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyRedate
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimRedated
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together (body {claimIds, user}).
# Each selected claim that can be opened (a DRAFT on the sheet, not due by a date in a closed period, with a note or a due not above the note threshold in force on
# its date) is
# opened and numbered in list order — people by their positions, a person's claims
# newest first — and recorded as CLAIM_OPENED, as a single open is; each that cannot is refused and
# left as it is. Answers {opened, refused}. Refused (400) only when no claim is selected.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: open
open:
  class: net.officefloor.hq.app.claim.OpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim's re-dating unless a steward re-dates an OPEN or PENDING claim to a date not after the
 *  date its person is retired from. Its due-by, and so its period, stays as it is, so the new date may fall in
 *  a closed period (a claim due by a date in one is refused before this). */
public class CheckRedate {
    public void check(@Val RedateInput input, @Val Claim claim, RoleStore roles, PersonStore people) throws InvalidSheetException {
        if (roles.find(claim.getSheetId(), input.user()) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward may re-date a claim");
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null) {
            Retirement.refuseClaimDate(person, input.date());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A validated re-dating: the claim's new date and who re-dates it. */
public record RedateInput(LocalDate date, String user) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRedate {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RedateRequest request, Out<RedateInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        String text = request == null || request.date() == null ? "" : request.date().trim();
        try {
            body.set(new RedateInput(LocalDate.parse(text), request.user()));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + text);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a stored re-dating: CLAIM_REDATED sheet=<id> by=<user> person=<name> amount=<0.00>
 *  date=<new yyyy-mm-dd> number=<n> old=<yyyy-mm-dd> new=<yyyy-mm-dd>. */
public class AuditClaimRedated {
    public void audit(@Val RedateInput input, @Val Claim claim, @Val Redating redating, @Val Rollup before,
            PersonStore people, Audit audit, RollupService rollups) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_REDATED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber())
                + " old=" + redating.old() + " new=" + redating.now());
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
package net.officefloor.hq.app.claim;

/** Body of a claim's re-dating, as sent: its new date (yyyy-MM-dd) and who re-dates it. */
public record RedateRequest(String date, String user) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Stores the claim's new date, keeping its due-by and any figure a statement bound it to. Its period
 *  is the one its due-by falls in, so it stays as it is, and so does its number. */
public class ApplyRedate {
    public void apply(@Val RedateInput input, @Val Claim claim, ClaimStore store, Out<Redating> redating)
            throws InvalidSheetException {
        LocalDate old = claim.getDate();
        if (!store.redate(claim, input.date(), claim.getNumber())) {
            throw new InvalidSheetException("The claim has moved on");
        }
        redating.set(new Redating(old, input.date()));
    }
}
